```html
<div class="carousel-ad" id="carousel-ad-300x250" data-ad-id="98765" data-campaign="new-launch">
 <style>
 .carousel-ad { width: 300px; height: 250px; overflow: hidden; position: relative; border: 1px solid #ccc; }
 .carousel-image { display: none; width: 100%; height: auto; }
 .carousel-active { display: block; }
 .indicator-dots { position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%); display: flex; }
 .dot { height: 10px; width: 10px; margin: 0 2px; background-color: #bbb; border-radius: 50%; cursor: pointer; }
 .dot-active { background-color: #717171; }
 </style>
 <div class="carousel-slides">
 <img class="carousel-image carousel-active" src="car1.jpg" alt="Car Model 1">
 <img class="carousel-image" src="car2.jpg" alt="Car Model 2">
 <img class="carousel-image" src="car3.jpg" alt="Car Model 3">
 </div>
 <div class="indicator-dots">
 <span class="dot dot-active"></span>
 <span class="dot"></span>
 <span class="dot"></span>
 </div>
 <script>
 const slides = document.querySelectorAll('.carousel-image');
 const dots = document.querySelectorAll('.dot');
 let currentIndex = 0;

 function showSlide(index) {
 slides[currentIndex].classList.remove('carousel-active');
 dots[currentIndex].classList.remove('dot-active');
 currentIndex = index;
 slides[currentIndex].classList.add('carousel-active');
 dots[currentIndex].classList.add('dot-active');
 }

 dots.forEach((dot, idx) => {
 dot.addEventListener('click', () => showSlide(idx));
 });
 </script>
 <ins class="adsbygoogle" data-ad-client="ca-pub-654321"></ins>
</div>
```
